# -*- coding: utf-8 -*-
# /tmp 원본(조례 페이지·별표 행 추출본)에서 evidence/law-*.txt 발췌본을 만든다
import sys, re, os, io
SRC, E = sys.argv[1], sys.argv[2]
M = [('jongno','종로구','서울특별시 종로구 폐기물관리 조례',2096877,'p_종로구'),('junggu','중구','서울특별시 중구 폐기물관리 조례',2042009,'p_중구'),('yongsan','용산구','서울특별시 용산구 폐기물관리 조례',2096899,'p_용산구'),('seongdong','성동구','서울특별시 성동구 폐기물관리 조례',1982305,'p_성동구'),('gwangjin','광진구','서울특별시 광진구 폐기물관리 조례',2034335,'p_광진구'),('dongdaemun','동대문구','서울특별시 동대문구 폐기물관리 조례',1890205,'p_동대문구'),('seongbuk','성북구','서울특별시 성북구 폐기물관리 조례',1980379,'p_성북구'),('gangbuk','강북구','서울특별시 강북구 폐기물관리 조례',2115267,'p_강북구'),('dobong','도봉구','서울특별시 도봉구 폐기물관리 조례',2037461,'p_도봉구'),('nowon','노원구R','서울특별시 노원구 폐기물관리 조례 시행규칙',2042631,'p_노원구R'),('eunpyeong','은평구','서울특별시 은평구 폐기물관리 조례',2096973,'p_은평구'),('seodaemun','서대문구','서울특별시 서대문구 폐기물관리 조례',2101297,'p_서대문구'),('mapo','마포구','서울특별시 마포구 폐기물관리 조례',2097023,'p_마포구'),('yangcheon','양천2','서울특별시 양천구 폐기물관리 조례',2176939,'p_양천구'),('gangseo','강서구','서울특별시 강서구 폐기물관리 조례',2120049,'p_강서구'),('guro','구로구','서울특별시 구로구 폐기물관리 조례',2137895,'p_구로구'),('geumcheon','금천구','서울특별시 금천구 폐기물관리 조례',2173463,'p_금천구'),('yeongdeungpo','영등포구','서울특별시 영등포구 폐기물관리 조례',2182385,'p_영등포구'),('dongjak','동작구','서울특별시 동작구 폐기물관리 조례',2176991,'p_동작구'),('gwanak','관악구','서울특별시 관악구 폐기물관리 조례',2173507,'p_관악구'),('seocho','서초구','서울특별시 서초구 폐기물관리 조례',1993571,'p_서초구'),('gangnam','강남구','서울특별시 강남구 폐기물관리 조례',2147835,'p_강남구'),('gangdong','강동구','서울특별시 강동구 폐기물관리 조례',2176401,'p_강동구'),('suwon','수원시2','경기도 수원시 폐기물관리에 관한 조례',1746547,'p_수원시2'),('goyang','고양시','경기도 고양시 폐기물관리 조례',2055485,'p_고양시'),('changwon','창원시','경상남도 창원시 폐기물관리 조례',2179195,'p_창원시')]
for key, k, name, seq, p in M:
    s = io.open(os.path.join(SRC, p + '.html'), encoding='utf-8').read()
    eff = re.search(r'시행 20[0-9. ]*\] \[[^\]]*\]', s).group(0)
    rows = io.open(os.path.join(SRC, 'rows', k + '.txt'), encoding='utf-8').read()
    with io.open(os.path.join(E, 'law-' + key + '-bulky-fee.txt'), 'w', encoding='utf-8') as f:
        f.write(u'https://www.law.go.kr/LSW/ordinInfoP.do?ordinSeq=%d\n' % seq)
        f.write(u'%s [%s\n' % (name, eff))
        f.write(u'국가법령정보센터 첨부 별표(HWP/HWPX)를 표 셀 주소 기준으로 행 단위 추출(T표 R행: 열=셀). curl 2026-11-08. 추출 도구: tools/hwp2rows.py\n\n')
        f.write(rows)
print('ok')
